import string

def normalize_tokens(tokens):
    out = []
    for t in tokens:
        t = t.lower().strip(string.punctuation)
        if t:
            out.append(t)
    return out

def build_vocab(token_lists):
    uniq = sorted({t for tokens in token_lists for t in tokens})
    return {t: i for i, t in enumerate(uniq)}

